// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierStateArena;
import org.junit.jupiter.api.Test;

class LmdbFrontierFilterOutcomeMemoTest {

	@Test
	void retainsAcceptRejectAndUnboundKeysAcrossGrowth() {
		try (FrontierStateArena arena = new FrontierStateArena(1L << 20);
				LmdbFrontierFilterOutcomeMemo memo = LmdbFrontierFilterOutcomeMemo.createIfCapacity(arena, 2)) {
			assertNotNull(memo);
			assertEquals(LmdbFrontierFilterOutcomeMemo.UNKNOWN, memo.get(new long[] { 11L, 0L }));
			memo.put(new long[] { 11L, 0L }, true);
			memo.put(new long[] { 11L, 22L }, false);
			for (int ordinal = 1; ordinal <= 100; ordinal++) {
				memo.put(new long[] { 100L + ordinal, -ordinal }, ordinal % 2 == 0);
			}

			assertEquals(LmdbFrontierFilterOutcomeMemo.ACCEPT, memo.get(new long[] { 11L, 0L }));
			assertEquals(LmdbFrontierFilterOutcomeMemo.REJECT, memo.get(new long[] { 11L, 22L }));
			for (int ordinal = 1; ordinal <= 100; ordinal++) {
				assertEquals(ordinal % 2 == 0
						? LmdbFrontierFilterOutcomeMemo.ACCEPT
						: LmdbFrontierFilterOutcomeMemo.REJECT,
						memo.get(new long[] { 100L + ordinal, -ordinal }));
			}
			assertEquals(102, memo.size());
			assertEquals(102L, memo.hits());
			assertEquals(1L, memo.misses());
			assertTrue(memo.retainedBytes() > 0L);
		}
	}

	@Test
	void zeroWidthMemoCachesOneQueryStableOutcome() {
		try (FrontierStateArena arena = new FrontierStateArena(4_096L);
				LmdbFrontierFilterOutcomeMemo memo = LmdbFrontierFilterOutcomeMemo.createIfCapacity(arena, 0)) {
			assertNotNull(memo);
			assertEquals(LmdbFrontierFilterOutcomeMemo.UNKNOWN, memo.get(new long[0]));
			memo.put(new long[0], false);
			assertEquals(LmdbFrontierFilterOutcomeMemo.REJECT, memo.get(new long[0]));
			assertEquals(1, memo.size());
		}
	}
}
